"""Generated notebook, editable copy, and workbench (plan §6, WP3.2; ADR 0001 decision 1).

``notebooks/study_generated.py`` is regenerated on every render:

* header "Regenerated by Hypotrail at revision N; open study_editable.py to adapt this
  notebook, or copy a cell to workbench.py for a separate experiment";
* setup cell: ``HYPOTRAIL_READ_ONLY=1``, the read API (through
  :mod:`mlkit.study.notebook_view`, which installs the read-only guard), and
  ``RESULT_IDS`` frozen at generation, so the numbers are those of the HTML report;
* a banner cell that says whether the study moved on since generation;
* one section per plan step: a Markdown cell with the question, the term first (its
  definition), and the method; then (v0.2a, WP-A6) readable pandas and scikit-learn cells
  that recompute the registered result from the development rows and ``assert`` that it
  equals the registry value (:mod:`mlkit.study.code_cells`, tolerances stated there); then
  the engine view cell: the contextual example with this study's cited numbers, the
  result, the interpretation, the decision, the consequence. A step without result says
  "Not executed yet".

Sources are produced with Marimo's own code generator
(``marimo._ast.codegen.generate_filecontents``, pinned ``marimo==0.25.1``), so an
unmodified editor save writes the same bytes back (ADR 0001 finding 5). The
revision-independent text is cached in ``.hypotrail/render-cache/`` so the code generator
is imported only when the notebook content changes (:func:`generate_study_source`).

Preservation. A user edit is any byte difference from the hash recorded in the
manifest, ignoring only the ``__generated_with`` version stamp. The edited file is
copied byte for byte to ``study_generated.user-edits-<rev>.py`` (``-2``, ``-3`` … if
that exists; created with ``O_EXCL``), where ``<rev>`` is the revision the edited file
was generated at, then regenerated. The hash is checked again immediately before
``os.replace``: an edit saved in between (Marimo autosaves) is preserved too.

``notebooks/study_editable.py`` follows the generated notebook until its first detected
user edit, then is never overwritten. ``notebooks/workbench.py`` is created once with
``O_EXCL`` and never written again. A template bump writes ``workbench.candidate.py``
instead.

This module writes files; it refuses to run in a read-only process
(``read_only``). It imports neither pandas nor scikit-learn: the recomputation cells it
writes import them when the notebook runs.
"""
from __future__ import annotations

import json
import os
import re
import uuid
from pathlib import Path
from typing import Any, Callable, Mapping

from . import code_cells, currency, guard, manifest as mf, render_html, texts
from .templates import workbench as wb_template

GENERATED = mf.ARTIFACTS['notebook']
EDITABLE = mf.ARTIFACTS['editable']
WORKBENCH = mf.ARTIFACTS['workbench']
CANDIDATE = 'notebooks/workbench.candidate.py'
STUDY_TEMPLATE_VERSION = 2
MAX_REPLACE_ATTEMPTS = 5

_TEMPLATE_VERSION = re.compile(rb'template_version = (\d+)')

# Test hook: called with the target path right before the final hash check and
# os.replace (simulates an editor autosave racing the render).
before_replace: Callable[[Path], None] | None = None


sha256 = currency.sha256
edit_check_sha256 = currency.edit_check_sha256


# --- generation -------------------------------------------------------------------------

def _codegen(header: str, cells: list[tuple[str, str]]) -> str:
    from marimo._ast.app_config import _AppConfig
    from marimo._ast.cell import CellConfig
    from marimo._ast.codegen import generate_filecontents

    return generate_filecontents([code for _, code in cells], [name for name, _ in cells],
                                 [CellConfig() for _ in cells], config=_AppConfig(),
                                 header_comments=header)


def result_ids(view: Mapping) -> dict[str, str]:
    """Slot -> result id of every citable result (current, integrity ok)."""
    return {slot: item['result_id'] for slot, item in sorted(view['results'].items())
            if item['current'] and item['integrity'] == 'ok'}


def _md_cell(text: str) -> str:
    """A Markdown cell in the triple-quoted form Marimo's codegen keeps."""
    if '"""' in text or '\\' in text or text.endswith('"'):
        return f'mo.md({text!r})'
    return 'mo.md(\n    r"""\n' + text + '\n"""\n)'


RECOMPUTE_NOTE = ('Each code cell below is the pandas (or scikit-learn) you would type on the '
                  'development rows, then an `assert` that its figure equals the registry. '
                  'Under review-v1, fitting uses the registered row-membership plan and model '
                  'comparison uses the predeclared business objective; pooled-count objectives '
                  'are not replaced by an equal-fold mean. Copy any cell to your workbench to '
                  'experiment.')
# WP-F2: the notebook narrative is in the study language where the engine provides French
# (WP-C: step titles and questions, glossary term names). Definitions, methods, and code
# comments have no French source yet and stay English.
RECOMPUTE_NOTE_FR = ("Chaque cellule de code ci-dessous est le pandas (ou scikit-learn) que vous "
                     "taperiez sur l'échantillon de développement, suivi d'un `assert` qui "
                     "vérifie que son résultat est celui du registre. Avec review-v1, "
                     "l'ajustement suit le plan d'appartenance enregistré et la comparaison "
                     "suit l'objectif métier pré-déclaré ; les comptages agrégés ne sont pas "
                     "remplacés par une moyenne simple des plis. Copiez les cellules dans votre "
                     "workbench pour expérimenter.")


def _step_markdown(index: int, step: Mapping, content: Mapping, pending: bool,
                   recompute: bool = False, lang: str = 'en') -> str:
    from . import junior

    fr = lang == junior.FR
    title = junior.step_text(step['title'], lang)
    question = junior.step_text(step['question'], lang)
    lines = [f'## {index}. {title}', '', f'**Question.** {question}']
    term = texts.glossary(content.get('concept')) if content.get('concept') else None
    if term:
        name = term['term_fr'] if fr and term.get('term_fr') else term['term']
        lines += ['', f'**{name[:1].upper() + name[1:]}.** {term["definition"]}']
    if content.get('method'):
        lines += ['', f'**Method.** {content["method"]}']
    if recompute:
        lines += ['', RECOMPUTE_NOTE_FR if fr else RECOMPUTE_NOTE]
    if pending:
        lines += ['', f'_{texts.load("steps")["pending"]}_']
    return '\n'.join(lines)


def _target(view: Mapping) -> tuple[str | None, object, dict]:
    """``(target column, positive label, case facts)`` of the study's case, or
    ``(None, None, {})``. The facts are what the exploration cells need beyond the registry:
    the values the case reads as missing and its special values."""
    from . import case as c

    try:
        case = c.load_case(view['case']['path'], verify_data=False)
    except Exception:          # the notebook still renders, without recomputation cells
        return None, None, {}
    facts = {'na_values': list(case.dataset.get('na_values') or ()),
             'special_values': [{'column': s['column'], 'value': s['value']}
                                for s in case.document.get('special_values') or []]}
    return case.target_column, case.positive_label, facts


# The generated text depends on the revision only through the header comment and the
# ``GENERATED_REVISION`` literal of the setup cell. The cells are generated once with this
# sentinel in their place, and the sentinel is then replaced by the revision: Marimo's
# codegen copies both verbatim, so the bytes equal a direct generation (tested).
REVISION_SENTINEL = 9_090_909_090_909
CACHE_FILE = 'render-cache/study_generated.json'


def _study_cells(view: Mapping, revision: Any) -> tuple[str, list[tuple[str, str]]]:
    with texts.study_context(view):
        return _study_cells_for_task(view, revision)


def _study_cells_for_task(view: Mapping, revision: Any) -> tuple[str, list[tuple[str, str]]]:
    rids = result_ids(view)
    task = view.get('task') or 'binary'
    # A regression notebook reads its texts for its task; a binary one stays byte-identical.
    task_arg = f', task={task!r}' if task != 'binary' else ''
    # B6c (M3): a cross-validated study reads its own texts at run time too.
    if texts.is_cv():
        task_arg += ", scheme='cross_validation'"
    header = (f'# Regenerated by Hypotrail at revision {revision}; open study_editable.py '
              'to adapt this notebook, or copy a cell to workbench.py for a separate experiment.\n'
              '# A modified copy is preserved as study_generated.user-edits-<rev>.py on the next '
              'render; this file itself remains read-only.\n'
              f'# template_version = {STUDY_TEMPLATE_VERSION}')
    setup = (wb_template.SETUP
             + f'\nGENERATED_REVISION = {revision!r}\n'
             + f'RESULT_IDS = {json.dumps(rids, sort_keys=True, indent=4)}')
    cells: list[tuple[str, str]] = [
        ('setup', setup),
        ('load_study', 'study = nv.open_study(STUDY_DIR)\ncited = nv.citer(study, RESULT_IDS)'),
        ('banner', 'mo.Html(nv.banner_html(study, GENERATED_REVISION, RESULT_IDS))'),
    ]
    target, positive, facts = _target(view)
    recompute = code_cells.cells_by_step(view, task, target, positive, facts,
                                         [step['id'] for step in view['plan']])
    if recompute:
        cells.append(('run_recompute',
                      'run_recompute = mo.ui.run_button(label="Run registered recomputations")\n'
                      'run_recompute'))
        guard = ('mo.stop(not (run_recompute.value or '
                 'os.environ.get("HYPOTRAIL_NOTEBOOK_RECOMPUTE") == "1"), '
                 'mo.md("Recomputation is paused until you press the run button."))\n')
        cells.append(('recompute_imports', guard + code_cells.imports(task)))
    for index, step in enumerate(view['plan'], start=1):
        content = texts.step(step['id'])
        slots = render_html.slots_of_step(step['id'], view['results'], task)
        has_result = any(s in rids for s in slots)
        # WP-A4: step 0 is informational; it is never "not executed".
        pending = not has_result and not step['decision'] and step['id'] != 'discover_data'
        code = recompute.get(step['id'], [])
        cells.append((f'step_{step["id"]}_text',
                      _md_cell(_step_markdown(index, step, content, pending, bool(code),
                                              view.get('language') or 'en'))))
        if pending:
            continue
        cells += [(name, guard + source) for name, source in code]
        concept = content.get('concept')
        items = [f'mo.Html(nv.example_html(cited, {concept!r}{task_arg}))',
                 f'mo.Html(nv.step_html(cited, RESULT_IDS, {slots!r}, '
                 f'{content.get("context", "")!r}, {content.get("interpretation", "")!r}'
                 f'{task_arg}))']
        if step['id'] == 'split' and code_cells.delayed_labels(view) is not None:
            # Review round 3 (E3-1): the rows the split leaves out for a delayed label, the
            # term first, then this study's example (the engine's limit, study language).
            items.append('mo.Html(nv.delayed_labels_html(study))')
        if step['decision']:
            items.append(f'mo.Html(nv.decision_html(study, {step["decision"]!r}))')
        if content.get('consequence'):
            items.append(f'mo.md({("**Consequence.** " + content["consequence"])!r})')
        body = 'mo.vstack(\n    [\n' + ''.join(f'        {i},\n' for i in items) + '    ]\n)'
        cells.append((f'step_{step["id"]}', body))
    return header, cells


def _marimo_version() -> str:
    from importlib import metadata

    try:
        return metadata.version('marimo')
    except metadata.PackageNotFoundError:
        return 'unknown'


def _cache_key(header: str, cells: list[tuple[str, str]]) -> str:
    return sha256(json.dumps({'header': header, 'cells': cells, 'marimo': _marimo_version(),
                              'template_version': STUDY_TEMPLATE_VERSION},
                             sort_keys=True).encode('utf-8'))


def generate_study_source(view: Mapping, *, cache_dir: Path | None = None) -> str:
    """The generated notebook source for ``view``.

    With ``cache_dir`` (the study's ``.hypotrail``), the revision-independent text is
    kept in ``render-cache/study_generated.json`` and Marimo's code generator (about half
    a second to import) is imported only when that text changes, which most decisions
    do not cause. The cache is an optimisation: an unreadable one is regenerated.
    """
    revision = view['revision']
    header, cells = _study_cells(view, REVISION_SENTINEL)
    sentinel = str(REVISION_SENTINEL)
    if any(sentinel in code for _, code in cells[1:]) or header.count(sentinel) != 1 \
            or cells[0][1].count(sentinel) != 1:
        return _codegen(*_study_cells(view, revision))     # never substitute ambiguously
    key = _cache_key(header, cells)
    path = cache_dir / CACHE_FILE if cache_dir is not None else None
    text = None
    if path is not None and path.is_file():
        try:
            cached = json.loads(path.read_text(encoding='utf-8'))
            if cached.get('key') == key and cached.get('text', '').count(sentinel) == 2:
                text = cached['text']
        except (ValueError, AttributeError, OSError):
            text = None
    if text is None:
        text = _codegen(header, cells)
        if text.count(sentinel) != 2:
            return _codegen(*_study_cells(view, revision))
        if path is not None:
            from .store import atomic_write_json

            atomic_write_json(path, {'key': key, 'text': text})
    return text.replace(sentinel, repr(revision))


def generate_workbench_source(template_version: int = wb_template.TEMPLATE_VERSION,
                              task: str = 'binary') -> str:
    return _codegen(wb_template.header(template_version),
                    wb_template.cells(template_version, task))


# --- writing ----------------------------------------------------------------------------

def _create_exclusive(path: Path, data: bytes) -> None:
    guard.assert_writable()
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    with os.fdopen(fd, 'wb') as handle:
        handle.write(data)
        handle.flush()
        os.fsync(handle.fileno())


def _preserve(study: Path, data: bytes, revision: Any) -> str:
    """Copy ``data`` to ``study_generated.user-edits-<rev>[-n].py``; return its path."""
    folder = study / 'notebooks'
    base = f'study_generated.user-edits-{revision if revision is not None else "unknown"}'
    counter = 1
    while True:
        name = f'{base}.py' if counter == 1 else f'{base}-{counter}.py'
        try:
            _create_exclusive(folder / name, data)
            return f'notebooks/{name}'
        except FileExistsError:
            counter += 1


def _is_edit(data: bytes, record: Mapping | None) -> bool:
    if record is None or not record.get('edit_check_sha256'):
        return True       # no record: a file we did not write, or a lost manifest
    return edit_check_sha256(data) != record['edit_check_sha256']


def _write_generated(study: Path, data: bytes, record: Mapping | None) -> list[str]:
    """Write the generated notebook, preserving every user edit first."""
    guard.assert_writable()
    path = study / GENERATED
    path.parent.mkdir(parents=True, exist_ok=True)
    preserved: list[str] = []
    expected = edit_check_sha256(data)
    known = dict(record or {})
    temp = path.with_name(f'.{path.name}.{os.getpid()}.{uuid.uuid4().hex[:8]}.tmp')
    try:
        with open(temp, 'wb') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        for _ in range(MAX_REPLACE_ATTEMPTS):
            current = path.read_bytes() if path.exists() else None
            if current is not None and _is_edit(current, known) \
                    and edit_check_sha256(current) != expected:
                preserved.append(_preserve(study, current, known.get('revision')))
            if before_replace is not None:
                before_replace(path)
            # Re-check immediately before the replace: an autosave in between is kept.
            again = path.read_bytes() if path.exists() else None
            if again == current:
                os.replace(temp, path)
                return preserved
            known = {'edit_check_sha256': edit_check_sha256(current) if current else None,
                     'revision': known.get('revision')}
        raise OSError('the generated notebook kept changing during the render')
    finally:
        temp.unlink(missing_ok=True)


def _file_template_version(data: bytes) -> int | None:
    m = _TEMPLATE_VERSION.search(data.split(b'\n\n', 1)[0])
    return int(m.group(1)) if m else None


def _editable_source(data: bytes, revision: int) -> bytes:
    notice = (
        '# EDITABLE HYPOTRAIL COPY — not official evidence.\n'
        f'# Synced from study_generated.py through revision {revision}; once you edit this '
        'file, Hypotrail never overwrites it.\n'
        '# Reproducible results remain in study_generated.py and reports/study.html.\n')
    return notice.encode('utf-8') + data


def _sync_editable(study: Path, data: bytes, manifest: Mapping, revision: int) -> dict:
    """Follow the generated notebook until the junior edits the editable copy."""
    from .store import atomic_write

    path = study / EDITABLE
    previous = manifest.get('artifacts', {}).get('editable') or {}
    current = path.read_bytes() if path.exists() else None
    owned = EDITABLE in (previous.get('user_edits_preserved') or [])
    untouched = not owned and (current is None or (previous.get('sha256') and
                                                   sha256(current) == previous.get('sha256')))
    record = mf.item(manifest, 'editable', kind='marimo_notebook', generated=False)
    record.update(status='ok', generated=False, error=None, consumed=[])
    if untouched:
        editable = _editable_source(data, revision)
        atomic_write(path, editable)
        record.update(revision=revision, sha256=sha256(editable),
                      last_ok_revision=revision, template_version=STUDY_TEMPLATE_VERSION,
                      candidate=None)
    elif not owned:
        # This marker makes ownership sticky even if the junior later restores the bytes of
        # an earlier engine-synchronised copy. It is a path, like the generated notebook's
        # preserved user-edit entries, and introduces no manifest key.
        record['user_edits_preserved'] = [EDITABLE]
    return record


def render(study_dir, view: Mapping, manifest: Mapping, *,
           workbench_template_version: int = wb_template.TEMPLATE_VERSION) -> dict:
    """Regenerate the notebook, sync its editable copy, and keep the workbench."""
    guard.assert_writable()
    study = Path(study_dir)
    revision = view['revision']

    record = mf.item(manifest, 'notebook', kind='marimo_notebook')
    data = generate_study_source(view, cache_dir=study / '.hypotrail').encode('utf-8')
    preserved = _write_generated(study, data, manifest.get('artifacts', {}).get('notebook'))
    record.update(revision=revision, status='ok', consumed=sorted(set(result_ids(view).values())),
                  sha256=sha256(data), edit_check_sha256=edit_check_sha256(data), generated=True,
                  template_version=STUDY_TEMPLATE_VERSION, error=None, last_ok_revision=revision,
                  user_edits_preserved=list(record.get('user_edits_preserved') or []) + preserved,
                  candidate=None)

    editable = _sync_editable(study, data, manifest, revision)

    workbench = study / WORKBENCH
    wb = mf.item(manifest, 'workbench', kind='marimo_notebook', generated=False)
    wb.update(status='ok', generated=False, error=None, consumed=[])
    task = view.get('task') or 'binary'
    if not workbench.exists():
        wb_data = generate_workbench_source(workbench_template_version, task).encode('utf-8')
        _create_exclusive(workbench, wb_data)
        wb.update(revision=revision, sha256=sha256(wb_data), sha256_at_creation=sha256(wb_data),
                  template_version=workbench_template_version, last_ok_revision=revision,
                  candidate=None)
    else:
        if wb.get('template_version') is None:
            wb['template_version'] = _file_template_version(workbench.read_bytes())
        if wb.get('revision') is None:
            wb['revision'] = revision
        if workbench_template_version > (wb.get('template_version') or 0):
            cand_path = study / CANDIDATE
            cand = generate_workbench_source(workbench_template_version, task).encode('utf-8')

            previous = (wb.get('candidate') or {}).get('sha256')
            if cand_path.exists() and sha256(cand_path.read_bytes()) not in (previous, sha256(cand)):
                # the user edited an earlier candidate: keep it, do not overwrite
                wb['candidate'] = dict(wb.get('candidate') or {}, kept_user_copy=True)
            else:
                from .store import atomic_write

                atomic_write(cand_path, cand)
                wb['candidate'] = {'path': CANDIDATE, 'template_version': workbench_template_version,
                                   'sha256': sha256(cand)}
    return {'notebook': record, 'editable': editable, 'workbench': wb,
            'preserved': preserved}
